double apply_operations(int input[], int size) {
    int final_count = 0;

    // First, keep only the numbers that are divisible by 5
    for (int i = 0; i < size; i++) {
        if (input[i] % 5 == 0) {
            final_count++;
        }
    }

    // Second, keep only the numbers that are odd
    for (int i = 0; i < size; i++) {
        if (input[i] % 2 != 0) {
            final_count++;
        }
    }

    // Third, keep only the numbers that are even
    for (int i = 0; i < size; i++) {
        if (input[i] % 2 == 0) {
            final_count++;
        }
    }

    // Fourth, keep only the numbers that are divisible by 3
    for (int i = 0; i < size; i++) {
        if (input[i] % 3 == 0) {
            final_count++;
        }
    }

    // Fifth, square each remaining number
    for (int i = 0; i < size; i++) {
        input[i] *= input[i];
    }

    return final_count;
}

